import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    features = torch.randn(6, generator=ctx.rng.torch)
    target = 0.5 * features[0] - 0.25 * features[1]
    return {"inputs": synth.Tensor(features), "targets": synth.Tensor(target)}
dataset = synth.Spec("crps-regression", generator=samples, size=16, splits={"train": 1.0}, seed=11, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class GaussianRegressor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=6, out_features=2)
    def forward(self, inputs):
        raw = self.network(inputs)
        return {"forecast": torch.stack((raw[..., 0], torch.nn.functional.softplus(raw[..., 1]) + 1e-4), dim=-1)}
model = GaussianRegressor()
trainer = Trainer(model, train, recipe="structured-objective", recipe_config={"loss": "crps", "bindings": {"logits_or_prediction": {"output": "forecast"}, "targets": {"batch": "targets"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
